import sys,re,statistics
pre=[];dec=[];run=[];q=[];thr=[];usage=[]
for l in sys.stdin:
    if l.startswith('Prefill'):
        m=dict(re.findall(r'#new-seq: (\d+), #new-token: (\d+), #cached-token: (\d+)',l) or [])
        mm=re.search(r'#new-token: (\d+), #cached-token: (\d+)',l)
        if mm: pre.append((int(mm.group(1)),int(mm.group(2))))
        qq=re.search(r'#queue-req: (\d+)',l)
        if qq: q.append(int(qq.group(1)))
    else:
        mm=re.search(r'#running-req: (\d+).*token usage: ([\d.]+).*gen throughput \(token/s\): ([\d.]+).*#queue-req: (\d+)',l)
        if mm: dec.append(int(mm.group(1))); usage.append(float(mm.group(2))); thr.append(float(mm.group(3))); q.append(int(mm.group(4)))
n=sum(a for a,b in pre); c=sum(b for a,b in pre)
print('prefill lines',len(pre),'new_tok',n,'cached',c,'hit%% %.1f'%(100*c/(n+c)))
print('decode lines',len(dec),'running mean %.2f max %d'%(statistics.fmean(dec),max(dec)))
print('usage p50 %.3f max %.3f'%(statistics.median(usage),max(usage)))
print('throughput mean %.1f p50 %.1f'%(statistics.fmean(thr),statistics.median(thr)))
print('queue-req max',max(q),'mean %.2f'%statistics.fmean(q))
"

