import gzip,json
from pathlib import Path
p=Path('/user/user1/autorlbench-runs/20261117023004-22299-5d0d/workspace/logs/public_rerun')
def pct(x,q):
 x=sorted(x); k=(len(x)-1)*q; a=int(k); b=min(a+1,len(x)-1); return x[a]+(x[b]-x[a])*(k-a)
for dname in ['env_setup','turns']:
 rows=[]
 for f in (p/dname).glob('*.jsonl.gz'):
  with gzip.open(f,'rt') as h:
   rows += [json.loads(x) for x in h if x.strip()]
 print(dname,'rows',len(rows),'keys', sorted(set().union(*(r.keys() for r in rows))))
 if dname=='env_setup':
  for k in ['semaphore_wait_s','sem_wait_s','create_s','tool_setup_s']:
   x=[r[k] for r in rows if k in r and isinstance(r[k],(int,float))]
   if x: print(k,len(x),'p50',pct(x,.5),'p90',pct(x,.9),'max',max(x))
  totals=[r.get('semaphore_wait_s',r.get('sem_wait_s',0))+r.get('create_s',0)+r.get('tool_setup_s',0) for r in rows]
  print('total setup p50/p90/max',pct(totals,.5),pct(totals,.9),max(totals))
  print('sample',json.dumps(rows[0],sort_keys=True))
 else:
  ev=[r for r in rows if r.get('event')=='abort' or r.get('finish')=='abort' or r.get('abort_reason')]
  print('abort rows',len(ev))
  if ev: print('first/last',min(str(r.get('timestamp',r.get('t',''))) for r in ev),max(str(r.get('timestamp',r.get('t',''))) for r in ev))
PY

